def calculate_wpm(characters: int, time_seconds: float) -> int:
    words = characters / 5
    minutes = time_seconds / 60
    return round(words / minutes)

score = calculate_wpm(300, 60)
print('Calculated Speed:', score, 'WPM')

def filter_active_users(users: list[dict]) -> list[str]:
    """Extract names of active users sorted alphabetically."""
    return sorted([
        u['name'] for u in users if u.get('is_active', False)
    ])

